<body class="custom">
<style>
    @keyframes light {
        0% {
            transform: rotateZ(4deg) translate(-0.5%, 0);
        }
        100% {
            transform: rotateZ(-4deg) translate(0.5%, 0);
        }
    }

    .preloader {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: #ffffff;
        z-index: 100;
        overflow: hidden;
    }

    .preloader__wrap {
        position: relative;
        width: 15rem;
        height: 15rem;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .preloader__img {
        display: block;
        width: 15rem;
        height: 13.6rem;
        position: relative;
        z-index: 1;
    }

    .preloader__svg {
        width: 100%;
        height: 100%;
        object-fit: contain;
        object-position: right top;
    }

    .preloader-light {
        transform-origin: center;
        animation: light 3s ease-in-out alternate-reverse infinite;
    }

    .preloader__grid {
        display: block;
        width: 100%;
        height: 100%;
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
    }

    ._colorBlack a {
        color: #1a1a1a;
        text-decoration: none;
        transition: 0.5s;
    }

    ._colorBlack a:hover {
        opacity: 0.5;
        transition: 0.5s;
    }

    form.res-message {
        font-size: 48px;
        text-align: center;
    }

    #map {
        width: 100%;
        height: 100%;
        padding: 0;
        margin: 0;
    }
</style>
